    @Test void concurrentDuplicateAndDistinctEventsHaveOneGrantAndOneDurableNotification()throws Exception{
        var f=fixture(false);gateway.paid(f.session());String id=eventId(),body=event(id,"checkout.session.completed",f.session(),false);var ready=new CountDownLatch(2);var go=new CountDownLatch(1);
        try(var executor=Executors.newFixedThreadPool(2)){var first=executor.submit(()->{ready.countDown();go.await();return webhook(body,signature(body));});var second=executor.submit(()->{ready.countDown();go.await();return webhook(body,signature(body));});assertThat(ready.await(3,TimeUnit.SECONDS)).isTrue();go.countDown();assertThat(first.get(10,TimeUnit.SECONDS).statusCode()).isEqualTo(200);assertThat(second.get(10,TimeUnit.SECONDS).statusCode()).isEqualTo(200);}
        assertThat(jdbc.queryForObject("SELECT count(*) FROM stripe_event_inbox WHERE event_id=?",Integer.class,id)).isEqualTo(1);
        try(var executor=Executors.newFixedThreadPool(2)){var a=executor.submit(worker::runOnce);var b=executor.submit(worker::runOnce);a.get(15,TimeUnit.SECONDS);b.get(15,TimeUnit.SECONDS);}
        until(()->ready(f.orderId()));String other=event(eventId(),"checkout.session.async_payment_succeeded",f.session(),false);assertThat(webhook(other,signature(other)).statusCode()).isEqualTo(200);until(()->jdbc.queryForObject("SELECT count(*) FROM stripe_event_inbox WHERE object_id=? AND state='PROCESSED'",Integer.class,f.session())==2);
        assertThat(grants(f.orderId())).isEqualTo(1);assertThat(notifications(f.orderId())).isEqualTo(1);assertThat(text(get(f.buyer(),statusPath(f)),"paymentStatus")).isEqualTo("PAID");
    }
