    @Test void missingSessionWaitsUntilItsPostgresDeadlineThenRemainsAnExplicitRecoverableIncident()throws Exception{
        var base=fixture(false);var waiting=historicalUnknown(base,20);var expired=historicalUnknown(base,120);int creates=gateway.creates.get();
        assertThat(jdbc.queryForObject("SELECT checkout_expires_at<=clock_timestamp() FROM checkout_operations WHERE id=?",Boolean.class,expired.operation())).isTrue();
        assertThat(jdbc.queryForObject("SELECT checkout_expires_at>clock_timestamp() FROM checkout_operations WHERE id=?",Boolean.class,waiting.operation())).isTrue();
        worker.runOnce();
        until(worker,()->"DEAD".equals(jdbc.queryForObject("SELECT state FROM payment_reconciliation_jobs WHERE operation_id=?",String.class,expired.operation())),()->paymentStateMetadata(expired));
        until(worker,()->"WAITING".equals(jdbc.queryForObject("SELECT state FROM payment_reconciliation_jobs WHERE operation_id=?",String.class,waiting.operation())),()->paymentStateMetadata(waiting));
        assertThat(jdbc.queryForObject("SELECT attempts FROM payment_reconciliation_jobs WHERE operation_id=?",Integer.class,waiting.operation())).isZero();
        assertThat(jdbc.queryForObject("SELECT state FROM checkout_operations WHERE id=?",String.class,waiting.operation())).isEqualTo("UNKNOWN");
        assertThat(jdbc.queryForObject("SELECT last_error_code FROM payment_reconciliation_jobs WHERE operation_id=?",String.class,expired.operation())).isEqualTo("SESSION_NOT_FOUND_AFTER_EXPIRY");
        assertThat(jdbc.queryForObject("SELECT state FROM checkout_operations WHERE id=?",String.class,expired.operation())).isEqualTo("NEEDS_REVIEW");
        assertThat(payment(expired.orderId())).isEqualTo("UNKNOWN");assertThat(jdbc.queryForObject("SELECT active_intention_key IS NOT NULL FROM orders WHERE id=?",Boolean.class,expired.orderId())).isTrue();
        assertThat(grants(expired.orderId())).isZero();assertThat(notifications(expired.orderId())).isZero();
        var status=get(expired.buyer(),statusPath(expired));assertThat(text(status,"checkoutUnavailableReason")).isEqualTo("RECONCILIATION_REQUIRED");assertThat(tree(status).path("canRetry").asBoolean()).isFalse();
        UUID work=jdbc.queryForObject("SELECT id FROM payment_reconciliation_jobs WHERE operation_id=?",UUID.class,expired.operation());var visible=get(expired.staff(),"/api/v1/admin/payment-events?state=DEAD");assertThat(visible.statusCode()).isEqualTo(200);assertThat(visible.body().contains(work.toString())).isTrue();
        var p=gateway.parameters.get(expired.operation());gateway.facts.put(expired.session(),GatewayDouble.value(p,expired.session(),"complete","paid","succeeded",p.amountMinor(),p.currency(),p.offerRevisionId().toString(),false));
        assertThat(mutate(expired.staff(),"POST","/api/v1/admin/payment-events/"+work+"/retry",Map.of("reason","MANUAL_RECONCILIATION"),null,null).statusCode()).isEqualTo(200);
        until(worker,()->ready(expired.orderId()),()->paymentStateMetadata(expired));assertThat(grants(expired.orderId())).isEqualTo(1);assertThat(notifications(expired.orderId())).isEqualTo(1);assertThat(gateway.creates.get()).isEqualTo(creates);
    }

    private Fixture historicalUnknown(Fixture base,int ageMinutes)throws Exception{
        // Explicit historical PostgreSQL fixtures; no real-time wait or alteration of immutable rows.
        Instant created=jdbc.queryForObject("SELECT date_trunc('second',clock_timestamp())-(?*interval '1 minute')",Timestamp.class,ageMinutes).toInstant();UUID orderId=UUID.randomUUID(),operation=UUID.randomUUID();
        var old=mapper.readValue(jdbc.queryForObject("SELECT snapshot_json::text FROM orders WHERE id=?",String.class,base.orderId()),OrderSnapshot.class);
        var lines=old.resources().stream().map(r->new OrderResource(UUID.randomUUID(),r.resourceId(),r.versionId(),r.versionNumber(),r.title(),r.slug(),r.locales())).toList();
        var snapshot=new OrderSnapshot(old.offerId(),old.offerRevision(),old.offerRevisionId(),old.code(),old.kind(),old.locale(),old.title(),lines,old.locales(),old.total(),old.tax(),old.conditions());
        String intention=HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(orderId.toString().getBytes(StandardCharsets.UTF_8)));
        jdbc.update("INSERT INTO orders(id,owner_id,offer_id,offer_revision,offer_revision_id,locale,total_amount,currency,order_status,payment_status,fulfillment_status,snapshot_json,accepted_terms_version,accepted_at,created_at,expires_at,active_intention_key) SELECT ?,owner_id,offer_id,offer_revision,offer_revision_id,locale,total_amount,currency,'AWAITING_PAYMENT','UNKNOWN','NOT_STARTED',?::jsonb,accepted_terms_version,?,?,?,? FROM orders WHERE id=?",orderId,mapper.writeValueAsString(snapshot),Timestamp.from(created),Timestamp.from(created),Timestamp.from(created.plusSeconds(1800)),intention,base.orderId());
        for(var line:lines)jdbc.update("INSERT INTO order_resources(id,order_id,resource_id,version_id,locales) VALUES(?,?,?,?,?::jsonb)",line.id(),orderId,line.resourceId(),line.versionId(),mapper.writeValueAsString(line.locales()));
        var p=new CheckoutParameters(operation,orderId,old.offerRevisionId(),old.locale(),old.title(),old.total().amountMinor(),old.total().currency(),"http://localhost:3000/fr/commandes/"+orderId+"/statut?checkout=success","http://localhost:3000/fr/commandes/"+orderId+"/statut?checkout=cancel",created.plusSeconds(3600));String json=mapper.writeValueAsString(p);
        jdbc.update("INSERT INTO checkout_operations(id,order_id,owner_id,order_revision,account_id,livemode,provider_idempotency_key,request_json,request_hash,amount_minor,currency,state,checkout_expires_at,retry_until,created_at,updated_at) VALUES(?,?,?,0,?,false,?,?::jsonb,?,?,?,'UNKNOWN',?,?,?,?)",operation,orderId,base.buyer().id(),ACCOUNT,"cc-checkout-"+operation,json,MessageDigest.getInstance("SHA-256").digest(json.getBytes(StandardCharsets.UTF_8)),p.amountMinor(),p.currency(),Timestamp.from(p.expiresAt()),Timestamp.from(created.plusSeconds(600)),Timestamp.from(created),Timestamp.from(created));
        jdbc.update("UPDATE orders SET payment_operation_id=?,revision=revision+1 WHERE id=?",operation,orderId);gateway.parameters.put(operation,p);
        return new Fixture(base.staff(),base.buyer(),base.source(),orderId,operation,gateway.session(operation));
    }

    private Fixture fixture(boolean lost)throws Exception{var staff=staff();var source=course(staff,"PROTECTED");var offer=activeOffer(staff,List.of(source),12345);var buyer=account();var prepared=order(buyer,command(offer),UUID.randomUUID().toString());UUID orderId=UUID.fromString(text(prepared,"id"));gateway.loseNext.set(lost);var access=mutate(buyer,"POST","/api/v1/me/orders/"+orderId+"/checkout",Map.of("acceptedTermsVersion","isolated-terms-v1"),etag(prepared),UUID.randomUUID().toString());assertThat(access.statusCode()).isEqualTo(lost?202:200);UUID operation=UUID.fromString(text(access,"operationId"));return new Fixture(staff,buyer,source,orderId,operation,gateway.session(operation));}
    private HttpResponse<String> webhook(String body,String signature)throws Exception{var request=HttpRequest.newBuilder(uri("/api/v1/webhooks/stripe")).timeout(Duration.ofSeconds(15)).header("Content-Type","application/json").POST(HttpRequest.BodyPublishers.ofString(body,StandardCharsets.UTF_8));if(signature!=null)request.header("Stripe-Signature",signature);return HttpClient.newHttpClient().send(request.build(),HttpResponse.BodyHandlers.ofString());}
    private String event(String id,String type,String session,boolean live)throws Exception{return mapper.writeValueAsString(Map.of("id",id,"object","event","type",type,"api_version",StripeSettings.API_VERSION,"created",Instant.now().getEpochSecond(),"livemode",live,"data",Map.of("object",Map.of("id",session,"object","checkout.session","payment_status","paid","customer_details",Map.of("email","not-stored@fixture.invalid")))));}
    private static String eventId(){return "evt_"+UUID.randomUUID().toString().replace("-","");}
    private static String signature(String body)throws Exception{long timestamp=Instant.now().getEpochSecond();var mac=Mac.getInstance("HmacSHA256");mac.init(new SecretKeySpec(SECRET.getBytes(StandardCharsets.UTF_8),"HmacSHA256"));return "t="+timestamp+",v1="+HexFormat.of().formatHex(mac.doFinal((timestamp+"."+body).getBytes(StandardCharsets.UTF_8)));}
    private boolean ready(UUID order){return "READY".equals(fulfillment(order));}private String payment(UUID order){return jdbc.queryForObject("SELECT payment_status FROM orders WHERE id=?",String.class,order);}private String fulfillment(UUID order){return jdbc.queryForObject("SELECT fulfillment_status FROM orders WHERE id=?",String.class,order);}private int grants(UUID order){return jdbc.queryForObject("SELECT count(*) FROM access_grants WHERE order_resource_id IN(SELECT id FROM order_resources WHERE order_id=?)",Integer.class,order);}private int notifications(UUID order){return jdbc.queryForObject("SELECT count(*) FROM notification_outbox WHERE business_key=?",Integer.class,"access:activated:"+order);}private String mailState(UUID order){return jdbc.queryForObject("SELECT status FROM notification_outbox WHERE business_key=?",String.class,"access:activated:"+order);}private String statusPath(Fixture f){return "/api/v1/me/orders/"+f.orderId()+"/payment-status";}
    private String paymentStateMetadata(Fixture f){return jdbc.queryForObject("SELECT concat('job=',coalesce(j.state,'ABSENT'),'/code=',coalesce(j.last_error_code,'NONE'),'; operation=',p.state,'/code=',coalesce(p.last_error_code,'NONE'),'; order=',o.order_status,'/payment=',o.payment_status,'/fulfillment=',o.fulfillment_status) FROM checkout_operations p JOIN orders o ON o.id=p.order_id LEFT JOIN payment_reconciliation_jobs j ON j.operation_id=p.id WHERE p.id=?",String.class,f.operation());}
    private void until(BooleanSupplier done){until(worker,done);}private void until(PaymentInboxWorker value,BooleanSupplier done){until(value,done,()->"Expected durable payment state without printing provider data");}private void until(PaymentInboxWorker value,BooleanSupplier done,java.util.function.Supplier<String> metadata){for(int i=0;i<100&&!done.getAsBoolean();i++)if(!value.runOnce())break;assertThat(done.getAsBoolean()).as(metadata).isTrue();}
    private record Fixture(Browser staff,Browser buyer,Map<String,Object> source,UUID orderId,UUID operation,String session){ }
    @TestConfiguration static class Doubles {@Bean @Primary GatewayDouble paymentTransport(){return new GatewayDouble();}@Bean @Primary EmailDouble isolatedEmailDelivery(){return new EmailDouble();}}
    static final class EmailDouble implements NotificationSender {final AtomicBoolean failActivation=new AtomicBoolean();@Override public void send(UUID id,NotificationTypes.Type type,NotificationTypes.Payload payload){if(type==NotificationTypes.Type.ACCESS_ACTIVATED&&failActivation.get())throw new RuntimeException("Controlled delivery failure",new java.net.ConnectException("Controlled test connection"));}}
    static final class GatewayDouble implements PaymentGateway {
        final Map<UUID,CheckoutParameters> parameters=new ConcurrentHashMap<>();final Map<String,CheckoutFacts> facts=new ConcurrentHashMap<>();final AtomicInteger creates=new AtomicInteger();final AtomicBoolean loseNext=new AtomicBoolean();final AtomicBoolean rejectNext=new AtomicBoolean();volatile java.util.function.Consumer<String> onCreated;
        @Override public boolean configured(){return true;}@Override public String unavailableReason(){return null;}
        @Override public CreatedCheckout createCheckout(CheckoutParameters p,String key){creates.incrementAndGet();if(rejectNext.getAndSet(false))throw new PaymentGatewayException("PROVIDER_REQUEST_INVALID",false);parameters.putIfAbsent(p.operationId(),p);String session=session(p.operationId());facts.putIfAbsent(session,value(p,session,"open","unpaid","requires_payment_method",p.amountMinor(),p.currency(),p.offerRevisionId().toString(),false));var callback=onCreated;if(callback!=null)callback.accept(session);if(loseNext.getAndSet(false))throw new PaymentGatewayException("PROVIDER_TRANSPORT_UNKNOWN",true);return new CreatedCheckout(session,url(session),p.expiresAt(),false,ACCOUNT);}
        @Override public CheckoutFacts retrieveCheckoutFacts(String session){var value=facts.get(session);if(value==null)throw new PaymentGatewayException("PROVIDER_REQUEST_INVALID",false);return value;}
        @Override public Optional<CheckoutFacts> findCheckoutFacts(CheckoutParameters p){return Optional.ofNullable(facts.get(session(p.operationId())));}
        String session(UUID operation){return "cs_test_"+operation.toString().replace("-","");}void paid(String session){var old=facts.get(session);var p=parameters.get(old.operationId());facts.put(session,value(p,session,"complete","paid","succeeded",p.amountMinor(),p.currency(),p.offerRevisionId().toString(),false));}void processing(String session){var old=facts.get(session);var p=parameters.get(old.operationId());facts.put(session,value(p,session,"complete","unpaid","processing",p.amountMinor(),p.currency(),p.offerRevisionId().toString(),false));}
        void corrupt(String session,String defect){var old=facts.get(session);var p=parameters.get(old.operationId());facts.put(session,value(p,session,"complete","paid","succeeded","amount".equals(defect)?p.amountMinor()+1:p.amountMinor(),"currency".equals(defect)?"USD":p.currency(),"product".equals(defect)?UUID.randomUUID().toString():p.offerRevisionId().toString(),"mode".equals(defect)));}
        private static String url(String session){return "https://checkout.stripe.com/c/pay/"+session+"#fidkd_SYNTHETIC_P12_ONLY";}
        private static CheckoutFacts value(CheckoutParameters p,String session,String state,String payment,String pi,long total,String currency,String product,boolean live){return new CheckoutFacts(session,p.operationId(),p.orderId(),p.orderId().toString(),live,ACCOUNT,StripeSettings.API_VERSION,"payment",state,payment,"pi_"+p.operationId().toString().replace("-",""),pi,total,"succeeded".equals(pi)?p.amountMinor():0L,currency,List.of(new CheckoutLine(product,total,currency,1)),0,Instant.now(),p.expiresAt(),url(session));}
    }

    private Map<String,Object> course(Browser staff,String access)throws Exception{var activity=content(staff,"ACTIVITY",access,List.of());var module=content(staff,"MODULE",access,List.of(text(activity,"versionId")));var course=content(staff,"COURSE",access,List.of(text(module,"versionId")));return Map.of("resourceId",text(course,"resourceId"),"versionId",text(course,"versionId"),"translationId",text(course,"id"));}
    private HttpResponse<String> content(Browser staff,String kind,String access,List<String> children)throws Exception{var doc=new LinkedHashMap<String,Object>();doc.put("objective","Identify confirmed facts");doc.put("expectedResult","A checked written brief");doc.put("prerequisites",List.of());doc.put("blocks",List.of(Map.of("type","PARAGRAPH","text","Fictional P11 integration fixture")));doc.put("estimatedMinutes",null);doc.put("exercise",Map.of("instructions","Check the supplied facts","correction","PRIVATE_TEST_CORRECTION"));doc.put("quiz",List.of());doc.put("rubric",List.of(Map.of("key","faithful","label","No invented facts","points",1,"blocking",true)));doc.put("access",access);doc.put("media",List.of());doc.put("relatedResourceIds",List.of());var body=new LinkedHashMap<String,Object>();body.put("kind",kind);body.put("locale","fr");body.put("slug",unique());body.put("title","Synthetic P11 "+kind);body.put("summary","Isolated integration fixture, not a commercial course");body.put("objectives","Check the brief");body.put("evaluationDefinition","Declarative checking only");body.put("document",doc);body.put("childVersionIds",children);body.put("reason","Create isolated commerce fixture");var created=mutate(staff,"POST","/api/v1/admin/contents",body,null,null);assertThat(created.statusCode()).isEqualTo(201);String path="/api/v1/admin/contents/"+text(created,"id");var review=mutate(staff,"POST",path+"/transition",Map.of("state","TO_REVIEW","reason","Explicit fixture review"),etag(created),null);assertThat(review.statusCode()).isEqualTo(200);var ready=mutate(staff,"POST",path+"/transition",Map.of("state","READY","reason","Explicit fixture readiness"),etag(review),null);assertThat(ready.statusCode()).isEqualTo(200);var published=mutate(staff,"POST",path+"/publish",Map.of("revisionId",text(ready,"currentRevisionId"),"reason","Explicit fixture publication"),etag(ready),null);assertThat(published.statusCode()).isEqualTo(200);return published;}
    private Map<String,Object> fields(List<Map<String,Object>> resources,Long amount){var f=new LinkedHashMap<String,Object>();f.put("copies",List.of(Map.of("locale","fr","title","Synthetic offer for tests only","summary","Fictional price and conditions; never a live commercial offer")));f.put("resources",resources.stream().map(x->Map.of("resourceId",x.get("resourceId"),"versionId",x.get("versionId"))).toList());f.put("locales",List.of("fr"));f.put("price",amount==null?null:Map.of("amountMinor",amount,"currency","EUR"));f.put("tax",Map.of("mode","INCLUSIVE","notices",List.of(Map.of("locale","fr","text","Synthetic tax presentation for isolated tests only"))));f.put("conditions",Map.of("access",Map.of("mode","FIXED","days",30),"updates",Map.of("mode","NONE"),"versionPolicy","PINNED","support",Map.of("mode","NONE","descriptions",List.of()),"humanReviewIncluded",false,"termsVersion","isolated-terms-v1","terms",List.of(Map.of("locale","fr","text","Synthetic isolated test conditions, not legal terms"))));return f;}
    private HttpResponse<String> createOffer(Browser staff,Map<String,Object> fields,String kind)throws Exception{var created=mutate(staff,"POST","/api/v1/admin/offers",Map.of("code",unique(),"kind",kind,"fields",fields,"reason","Create synthetic isolated offer"),null,null);assertThat(created.statusCode()).isEqualTo(201);return created;}
    private HttpResponse<String> activeOffer(Browser staff,List<Map<String,Object>> resources,long amount)throws Exception{var created=createOffer(staff,fields(resources,amount),resources.size()>1?"PACK":"COURSE");var result=mutate(staff,"POST","/api/v1/admin/offers/"+text(created,"id")+"/activate",Map.of("reason","Explicit synthetic activation"),etag(created),null);assertThat(result.statusCode()).isEqualTo(200);return result;}
    private List<Map<String,Object>> resources(HttpResponse<String> offer)throws Exception{var list=new ArrayList<Map<String,Object>>();for(var item:tree(offer).path("fields").path("resources"))list.add(Map.of("resourceId",item.path("resourceId").asText(),"versionId",item.path("versionId").asText()));return list;}
    private Map<String,Object> command(HttpResponse<String> offer)throws Exception{return Map.of("offerId",text(offer,"id"),"offerRevision",tree(offer).path("revision").asLong(),"locale","fr","acceptedTermsVersion","isolated-terms-v1");}
    private void grant(Browser owner,Map<String,Object> source){jdbc.update("INSERT INTO access_grants(id,owner_id,resource_id,version_id,origin_type,manual_origin_id,locales,version_policy,starts_at,expires_at) VALUES(?,?,?,?,'MANUAL_TEST',?,'[\"fr\"]'::jsonb,'PINNED',clock_timestamp()-interval '1 second',clock_timestamp()+interval '1 day')",UUID.randomUUID(),owner.id(),UUID.fromString(source.get("resourceId").toString()),UUID.fromString(source.get("versionId").toString()),UUID.randomUUID());}
    private Browser staff()throws Exception{return account("EDITOR","COMMERCE_MANAGER","PAYMENTS_OPERATOR");}
    private Browser account(String... roles)throws Exception{var browser=browser();String email=unique()+"@courses.invalid",password=unique()+"-credential";var created=send(browser,"POST","/api/v1/auth/register",Map.of("email",email,"password",password,"locale","fr"),csrf(browser),null,null,null);assertThat(created.statusCode()).isEqualTo(201);UUID id=UUID.fromString(text(created,"id"));for(String role:roles)assertThat(jdbc.update("INSERT INTO user_roles(id,user_id,role_id) SELECT ?,?,id FROM roles WHERE code=?",UUID.randomUUID(),id,role)).isEqualTo(1);var request=HttpRequest.newBuilder(uri("/api/v1/auth/login")).header("Content-Type","application/x-www-form-urlencoded").header("X-CSRF-TOKEN",csrf(browser)).POST(HttpRequest.BodyPublishers.ofString("email="+URLEncoder.encode(email,StandardCharsets.UTF_8)+"&password="+URLEncoder.encode(password,StandardCharsets.UTF_8))).build();assertThat(browser.http().send(request,HttpResponse.BodyHandlers.ofString()).statusCode()).isEqualTo(200);return new Browser(browser.http(),id);}
    private HttpResponse<String> order(Browser owner,Object body,String key)throws Exception{return mutate(owner,"POST","/api/v1/me/orders",body,null,key);}
    private HttpResponse<String> mutate(Browser who,String method,String path,Object body,String tag,String key)throws Exception{return send(who,method,path,body,csrf(who),tag,key,who.id()==null?null:who.id().toString());}
    private HttpResponse<String> send(Browser who,String method,String path,Object body,String token,String tag,String key,String context)throws Exception{var request=HttpRequest.newBuilder(uri(path)).timeout(Duration.ofSeconds(20)).header("Content-Type","application/json").method(method,HttpRequest.BodyPublishers.ofString(mapper.writeValueAsString(body)));if(token!=null)request.header("X-CSRF-TOKEN",token);if(tag!=null)request.header("If-Match",tag);if(key!=null)request.header("Idempotency-Key",key);if(context!=null)request.header("X-Account-Context",context);return who.http().send(request.build(),HttpResponse.BodyHandlers.ofString());}
    private String csrf(Browser who)throws Exception{return text(get(who,"/api/v1/auth/csrf"),"token");}
    private HttpResponse<String> get(Browser who,String path)throws Exception{return who.http().send(HttpRequest.newBuilder(uri(path)).timeout(Duration.ofSeconds(20)).GET().build(),HttpResponse.BodyHandlers.ofString());}
    private void problem(HttpResponse<String> value,int status,String code)throws Exception{assertThat(value.statusCode()).isEqualTo(status);assertThat(text(value,"code")).isEqualTo(code);assertThat(text(value,"type")).isEqualTo("about:blank");assertThat(value.body().contains("password")).isFalse();}
    private JsonNode tree(HttpResponse<String> value)throws Exception{return mapper.readTree(value.body());}private String text(HttpResponse<String> value,String key)throws Exception{return tree(value).path(key).asText();}
    private static String etag(HttpResponse<String> value){return value.headers().firstValue("ETag").orElseThrow();}private URI uri(String path){return URI.create("http://127.0.0.1:"+port+path);}private static String unique(){return "p12-worker-"+UUID.randomUUID();}
    private static Browser browser(){return new Browser(HttpClient.newBuilder().cookieHandler(new CookieManager(null,CookiePolicy.ACCEPT_ALL)).connectTimeout(Duration.ofSeconds(3)).build(),null);}private record Browser(HttpClient http,UUID id) { }
